import LandbotFacade from '../components/LandbotFacade'
import PageBanner from '../components/PageBanner'

/**
 * /hair-assessment/ -- the AI hair assessment chatbot.
 *
 * NO GENERATED MARKER, DELIBERATELY. scripts/gen-pages.mjs overwrites any page
 * file still carrying `// GENERATED by scripts/gen-pages.mjs`.
 *
 * THE CAPTURE IS NINE WORDS. neofollicle-seo-backup/pages/hair-assessment/
 * has no headings at all and its entire body text is "Landbot | Convert a
 * Landing Page into a Chatbot" -- the vendor's own <title>, left in by
 * accident. The page WAS the chatbot and nothing else: no copy to port.
 *
 * So the supporting copy below is authored, not ported. It is the only page in
 * this rebuild where that is true, and it is written to match the three steps
 * the sibling calculator page states ("Take A Photo" / "Wait for the AI to
 * analyze your images" / "Get Your Report"), because both pages front the same
 * assessment flow.
 *
 * ONE OF THE SIX noindex AD LANDING PAGES -- no canonical, not in the sitemap.
 * scripts/verify-seo.mjs asserts both. Nothing here may touch src/seo/.
 *
 * The capture has no h1 (seoFor('hair-assessment').h1 is null), so PageBanner's
 * title is the page's one h1 and is written here rather than read from the SEO
 * record, which has nothing to give.
 */
export default function HairAssessment() {
  return (
    <>
      <PageBanner
        crumbs={[{ label: 'Home', to: '/' }, { label: 'Hair Assessment' }]}
        image="/hero.webp"
        title="Free AI Hair Assessment"
      />

      <LandbotFacade
        /*
          The bot behind the old page, unchanged --
          landbot.pro/v3/H-3082458-C4Q4SEVC54EBQLPP, read out of
          neofollicle-seo-backup/pages/hair-assessment/raw.html. Keeping the
          same bot keeps the leads flowing to wherever they already go; a new
          one would silently break that.
        */
        configUrl="https://storage.googleapis.com/landbot.pro/v3/H-3082458-C4Q4SEVC54EBQLPP/index.json"
        heading="Check Your Hair Loss Grade in a Few Minutes"
        lede="Answer a short set of questions and upload a photo. You will get an assessment of your hair loss pattern and an indication of what treatment may suit you."
        steps={[
          { title: 'Take a photo', body: 'Upload clear photos of your hairline, crown and donor area.' },
          { title: 'AI analyses it', body: 'The assessment reviews your pattern, density and stage of hair loss.' },
          { title: 'Get your report', body: 'Receive your report by email, then talk it through with our team.' },
        ]}
        startLabel="Start Free Hair Assessment"
        note="Takes about 3 minutes. No payment required."
      />
    </>
  )
}
